import{_ as e,o as t,a as i,b as o}from"./app.C41L12d5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子性能优化","link":"/guide/operator_practice/simd_operator_optimization/simd_operator_optimization"},{"text":"头尾开销优化","link":"/guide/operator_practice/simd_operator_optimization/overhead_optimization/overhead_optimization"},{"text":"设置DCI编译选项来减少算子尾开销","link":"/guide/operator_practice/simd_operator_optimization/overhead_optimization/dci_compile_option"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_optimization/overhead_optimization/dci_compile_option.md","filePath":"guide/operator_practice/simd_operator_optimization/overhead_optimization/dci_compile_option.md","lastUpdated":1786954352000}'),_={name:"guide/operator_practice/simd_operator_optimization/overhead_optimization/dci_compile_option.md"};function r(c,a,p,n,d,l){return t(),i("div",null,[...a[0]||(a[0]=[o('<div><article class="markdown-body"><h1>设置DCI编译选项来减少算子尾开销<span id="ZH-CN_TOPIC_0000002531100207"></span></h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 该性能优化建议适用于如下型号：</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div></div><p>【优先级】高</p><p>【描述】算子执行结束时，需要将DCache置为无效，防止后续算子继续使用DCache中的数据而受到影响。可以通过在编译选项中添加--cce-no-dcache-flush，用于在算子尾部增加DCI（DataCacheInvalid）指令来使DCache失效。如果不开启该选项，则会默认增加DCCI（DataCacheCleanAndInvalid）指令来使DCache失效。</p><p>插入DCI指令相比于插入DCCI指令，其减少了数据从DCache同步到GM（Clean）的过程，性能上会有一定优势。插入DCCI是一种额外的容错保证，如果开发者使用了* __gm__的方式改写GM内存，或者调用GlobalTensor.SetValue函数时，没有正确的调用DataCacheCleanAndInvalid接口来保证Cache一致性，编译框架自动插入DCCI恰好可以保证算子精度正常。</p><p>所以在如下场景，可以通过开启该编译选项来降低算子尾部开销：</p><ul><li>算子使用* __gm__的方式改写GM内存，或者调用GlobalTensor.SetValue函数时，正确的使用DataCacheCleanAndInvalid接口，手动将数据从DCache中回刷到GM上，保证Cache的一致性。不依赖编译框架自动插入DCCI指令来保证一致性。</li><li>算子不包含使用* __gm__的方式改写GM内存，或者调用GlobalTensor.SetValue函数的代码。</li></ul></article></div>',1)])])}const h=e(_,[["render",r]]);export{m as __pageData,h as default};
